namespace CourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string Room { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public Instructor Instructor { get; set; } = new();
}

namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Abbreviation { get; set; } = string.Empty;
}

namespace CourseCatalog.Models;

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be 2 letters followed by 6 digits (e.g., CS123456).")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public interface ICatalogService
{
    Task<List<Department>> GetDepartmentsAsync();
    Task<List<Course>> GetCoursesAsync(string? searchTerm = null, int? departmentId = null);
    Task<List<Course>> GetFeaturedCoursesAsync();
    Task<Course?> GetCourseByIdAsync(int id);
    Task<bool> SubmitEnrollmentAsync(EnrollmentRequest request);
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class InMemoryCatalogService : ICatalogService
{
    private static readonly List<Department> Departments =
    [
        new() { Id = 1, Name = "Computer Science", Abbreviation = "CS" },
        new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH" },
        new() { Id = 3, Name = "Physics", Abbreviation = "PHYS" },
        new() { Id = 4, Name = "English", Abbreviation = "ENGL" },
        new() { Id = 5, Name = "History", Abbreviation = "HIST" },
    ];

    private static readonly List<Instructor> Instructors =
    [
        new() { Id = 1, Name = "Dr. Ada Lovelace", Title = "Professor", Email = "alovelace@university.edu", Bio = "Pioneer in computing theory with 20 years of teaching experience. Research interests include algorithm design, formal verification, and programming language theory." },
        new() { Id = 2, Name = "Dr. Alan Turing", Title = "Associate Professor", Email = "aturing@university.edu", Bio = "Specialist in computational complexity and artificial intelligence. Published over 50 papers on machine learning and automata theory." },
        new() { Id = 3, Name = "Dr. Emmy Noether", Title = "Professor", Email = "enoether@university.edu", Bio = "Award-winning mathematician focused on abstract algebra and theoretical physics. Known for making complex topics accessible to students." },
        new() { Id = 4, Name = "Dr. Richard Feynman", Title = "Distinguished Professor", Email = "rfeynman@university.edu", Bio = "Renowned physicist and science communicator. Brings real-world applications and humor to every lecture." },
        new() { Id = 5, Name = "Dr. Toni Morrison", Title = "Professor", Email = "tmorrison@university.edu", Bio = "Acclaimed author and literary scholar specializing in American literature, narrative theory, and creative writing." },
        new() { Id = 6, Name = "Dr. Howard Zinn", Title = "Associate Professor", Email = "hzinn@university.edu", Bio = "Historian focusing on social movements, civil rights, and labor history in the United States." },
    ];

    private static readonly List<Course> Courses =
    [
        new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "A broad introduction to computer science covering computational thinking, basic programming in Python, data representation, and an overview of major CS subfields. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Room = "Science Hall 201", IsFeatured = true, DepartmentId = 1, DepartmentName = "Computer Science", Instructor = Instructors[0] },
        new() { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, hash tables, graphs) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms). Includes weekly programming assignments.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Room = "Science Hall 305", IsFeatured = true, DepartmentId = 1, DepartmentName = "Computer Science", Instructor = Instructors[1] },
        new() { Id = 3, Code = "CS 310", Title = "Database Systems", Description = "Relational database design, SQL, normalization, transaction processing, and an introduction to NoSQL databases. Students build a complete database-backed application as a semester project.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Room = "Science Hall 110", IsFeatured = false, DepartmentId = 1, DepartmentName = "Computer Science", Instructor = Instructors[0] },
        new() { Id = 4, Code = "CS 420", Title = "Artificial Intelligence", Description = "Foundations of AI including search algorithms, knowledge representation, machine learning basics, neural networks, and ethical considerations in AI development.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Room = "Science Hall 401", IsFeatured = true, DepartmentId = 1, DepartmentName = "Computer Science", Instructor = Instructors[1] },
        new() { Id = 5, Code = "MATH 151", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics. Emphasis on both computational fluency and conceptual understanding.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Room = "Math Building 102", IsFeatured = true, DepartmentId = 2, DepartmentName = "Mathematics", Instructor = Instructors[2] },
        new() { Id = 6, Code = "MATH 250", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and eigenvectors. Applications in computer graphics, data science, and engineering.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Room = "Math Building 205", IsFeatured = false, DepartmentId = 2, DepartmentName = "Mathematics", Instructor = Instructors[2] },
        new() { Id = 7, Code = "MATH 301", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, regression analysis, and Bayesian inference. Uses R for statistical computing.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Room = "Math Building 310", IsFeatured = false, DepartmentId = 2, DepartmentName = "Mathematics", Instructor = Instructors[2] },
        new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Algebra-based approach suitable for life science majors and students seeking a broad physics foundation. Includes weekly lab sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Room = "Physics Lab 100", IsFeatured = false, DepartmentId = 3, DepartmentName = "Physics", Instructor = Instructors[3] },
        new() { Id = 9, Code = "PHYS 201", Title = "Modern Physics", Description = "Special relativity, quantum mechanics, atomic structure, nuclear physics, and particle physics. Calculus-based prerequisite required.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", Room = "Physics Lab 210", IsFeatured = true, DepartmentId = 3, DepartmentName = "Physics", Instructor = Instructors[3] },
        new() { Id = 10, Code = "ENGL 101", Title = "English Composition", Description = "Fundamentals of academic writing: thesis development, argument structure, research methods, and revision strategies. Students write four major essays across different genres.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Room = "Humanities 150", IsFeatured = false, DepartmentId = 4, DepartmentName = "English", Instructor = Instructors[4] },
        new() { Id = 11, Code = "ENGL 220", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present. Explores themes of identity, freedom, and the American experience through novels, poetry, and essays.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Room = "Humanities 220", IsFeatured = false, DepartmentId = 4, DepartmentName = "English", Instructor = Instructors[4] },
        new() { Id = 12, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, cultural exchanges, and turning points in world history from prehistory to the early modern period.", Credits = 3, Schedule = "Mon/Wed/Fri 2:00–2:50 PM", Room = "Liberal Arts 300", IsFeatured = false, DepartmentId = 5, DepartmentName = "History", Instructor = Instructors[5] },
        new() { Id = 13, Code = "HIST 250", Title = "The American Civil Rights Movement", Description = "In-depth study of the Civil Rights Movement from the 1950s to 1970s. Examines key events, leaders, legal battles, and the lasting impact on American society.", Credits = 3, Schedule = "Tue/Thu 3:30–4:50 PM", Room = "Liberal Arts 315", IsFeatured = true, DepartmentId = 5, DepartmentName = "History", Instructor = Instructors[5] },
    ];

    public Task<List<Department>> GetDepartmentsAsync()
    {
        return Task.FromResult(Departments.ToList());
    }

    public Task<List<Course>> GetCoursesAsync(string? searchTerm = null, int? departmentId = null)
    {
        var query = Courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        return Task.FromResult(query.ToList());
    }

    public Task<List<Course>> GetFeaturedCoursesAsync()
    {
        return Task.FromResult(Courses.Where(c => c.IsFeatured).ToList());
    }

    public Task<Course?> GetCourseByIdAsync(int id)
    {
        return Task.FromResult(Courses.FirstOrDefault(c => c.Id == id));
    }

    public Task<bool> SubmitEnrollmentAsync(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return Task.FromResult(true);
    }
}

