arguments.file_text:
@using CourseCatalog.Models

<div class="card h-100 shadow-sm border-0">
    <div class="card-body">
        <span class="badge bg-primary mb-2">@Course.Code</span>
        <h5 class="card-title">@Course.Title</h5>
        <p class="card-text text-muted small mb-2">@Course.DepartmentName &middot; @Course.Credits credits</p>
        <p class="card-text">@Truncate(Course.Description, 120)</p>
    </div>
    <div class="card-footer bg-transparent border-0">
        <a href="@($"courses/{Course.Id}")" class="btn btn-outline-primary btn-sm">View Details</a>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Course Course { get; set; } = default!;

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

.department-link-card {
    transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.department-link-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.12) !important;
}

@using CourseCatalog.Models

<div class="d-flex align-items-start">
    <div class="bg-primary text-white rounded-circle d-flex align-items-center justify-content-center me-3 flex-shrink-0" style="width:56px;height:56px;font-size:1.4rem;">
        @Instructor.Name[0]
    </div>
    <div>
        <h5 class="mb-0">@Instructor.Name</h5>
        <p class="text-muted small mb-1">@Instructor.Title &middot; <a href="@($"mailto:{Instructor.Email}")">@Instructor.Email</a></p>
        <p class="mb-0">@Instructor.Bio</p>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Instructor Instructor { get; set; } = default!;
}

@using CourseCatalog.Models

<div class="row g-3 mb-4">
    <div class="col-md-8">
        <input type="text"
               class="form-control"
               placeholder="Search by title, code, or instructor…"
               @bind="SearchTerm"
               @bind:event="oninput"
               @bind:after="OnFilterChanged" />
    </div>
    <div class="col-md-4">
        <select class="form-select" @bind="SelectedDepartmentId" @bind:after="OnFilterChanged">
            <option value="0">All Departments</option>
            @foreach (var dept in Departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
</div>

@code {
    [Parameter] public string SearchTerm { get; set; } = string.Empty;
    [Parameter] public int SelectedDepartmentId { get; set; }
    [Parameter] public List<Department> Departments { get; set; } = [];
    [Parameter] public EventCallback<(string SearchTerm, int DepartmentId)> OnFiltersChanged { get; set; }

    private async Task OnFilterChanged()
    {
        await OnFiltersChanged.InvokeAsync((SearchTerm, SelectedDepartmentId));
    }
}

@using CourseCatalog.Models

<div class="card h-100 shadow-sm border-0">
    <div class="card-body">
        <span class="badge bg-primary mb-2">@Course.Code</span>
        <h5 class="card-title">@Course.Title</h5>
        <p class="card-text text-muted small mb-2">@Course.DepartmentName &middot; @Course.Credits credits</p>
