@page "/"
@using CourseCatalog.Services
@using CourseCatalog.Models
@using CourseCatalog.Components.Shared
@inject ICatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="text-center py-5 mb-4 bg-light rounded-3">
    <h1 class="display-5 fw-bold">University Course Catalog</h1>
    <p class="lead text-muted">Browse departments, explore courses, and request enrollment — all in one place.</p>
    <a href="courses" class="btn btn-primary btn-lg me-2">Browse Courses</a>
    <a href="enroll" class="btn btn-outline-secondary btn-lg">Request Enrollment</a>
</div>

<section class="mb-5">
    <h2 class="mb-3">Featured Courses</h2>
    @if (featuredCourses is null)
    {
        <p class="text-muted">Loading…</p>
    }
    else
    {
        <div class="row row-cols-1 row-cols-md-3 g-4">
            @foreach (var course in featuredCourses)
            {
                <div class="col">
                    <FeaturedCourseCard Course="course" />
                </div>
            }
        </div>
    }
</section>

<section>
    <h2 class="mb-3">Departments</h2>
    @if (departments is null)
    {
        <p class="text-muted">Loading…</p>
    }
    else
    {
        <div class="row row-cols-2 row-cols-md-5 g-3">
            @foreach (var dept in departments)
            {
                <div class="col">
                    <DepartmentLinkCard Department="dept" />
                </div>
            }
        </div>
    }
</section>

@code {
    private List<Course>? featuredCourses;
    private List<Department>? departments;

    protected override async Task OnInitializedAsync()
    {
        featuredCourses = await CatalogService.GetFeaturedCoursesAsync();
        departments = await CatalogService.GetDepartmentsAsync();
    }
}

