@page "/courses"
@using CourseCatalog.Services
@using CourseCatalog.Models
@using CourseCatalog.Components.Shared
@inject ICatalogService CatalogService

<PageTitle>Browse Courses — University Course Catalog</PageTitle>

<h1 class="mb-4">Browse Courses</h1>

<CourseFilters SearchTerm="@searchTerm"
              SelectedDepartmentId="@selectedDepartmentId"
              Departments="@(departments ?? [])"
              OnFiltersChanged="HandleFiltersChanged" />

@if (courses is null)
{
    <p class="text-muted">Loading courses…</p>
}
else if (courses.Count == 0)
{
    <div class="alert alert-info">
        No courses match your search. Try adjusting your filters.
    </div>
}
else
{
    <p class="text-muted mb-3">Showing @courses.Count course(s)</p>
    @foreach (var course in courses)
    {
        <CourseListItem Course="course" />
    }
}

@code {
    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }

    private List<Course>? courses;
    private List<Department>? departments;
    private string searchTerm = string.Empty;
    private int selectedDepartmentId;

    protected override async Task OnInitializedAsync()
    {
        selectedDepartmentId = DepartmentId ?? 0;
        departments = await CatalogService.GetDepartmentsAsync();
        courses = await CatalogService.GetCoursesAsync(searchTerm, selectedDepartmentId > 0 ? selectedDepartmentId : null);
    }

    private async Task HandleFiltersChanged((string SearchTerm, int DepartmentId) filters)
    {
        searchTerm = filters.SearchTerm;
        selectedDepartmentId = filters.DepartmentId;
        courses = await CatalogService.GetCoursesAsync(
            searchTerm,
            selectedDepartmentId > 0 ? selectedDepartmentId : null);
    }
}

@page "/courses/{Id:int}"
@using CourseCatalog.Services
@using CourseCatalog.Models
@using CourseCatalog.Components.Shared
@inject ICatalogService CatalogService

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <div class="alert alert-warning">Course not found. <a href="courses">Back to course list</a>.</div>
}
else
{
    <PageTitle>@course.Code @course.Title — University Course Catalog</PageTitle>

    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.Code</li>
        </ol>
    </nav>

    <div class="row">
        <div class="col-lg-8">
            <span class="badge bg-primary mb-2">@course.DepartmentName</span>
            <h1>@course.Code — @course.Title</h1>
            <p class="lead">@course.Description</p>

            <hr />

            <h4 class="mt-4 mb-3">Instructor</h4>
            <InstructorBio Instructor="course.Instructor" />
        </div>

        <div class="col-lg-4">
            <div class="card border-0 shadow-sm">
                <div class="card-body">
                    <h5 class="card-title">Course Details</h5>
                    <ul class="list-unstyled mb-0">
                        <li class="mb-2"><strong>Credits:</strong> @course.Credits</li>
                        <li class="mb-2"><strong>Schedule:</strong> @course.Schedule</li>
                        <li class="mb-2"><strong>Room:</strong> @course.Room</li>
                        <li class="mb-2"><strong>Department:</strong> @course.DepartmentName</li>
                    </ul>
                    <hr />
                    <a href="@($"enroll?courseId={course.Id}")" class="btn btn-primary w-100">Request Enrollment</a>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? course;

    protected override async Task OnInitializedAsync()
    {
        course = await CatalogService.GetCourseByIdAsync(Id);
    }
}

@page "/enroll"
@using CourseCatalog.Services
@using CourseCatalog.Models
@inject ICatalogService CatalogService

<PageTitle>Request Enrollment — University Course Catalog</PageTitle>

<h1 class="mb-4">Request Enrollment</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Enrollment Request Submitted</h4>
        <p>Thank you, <strong>@model.StudentName</strong>. Your request to enroll in
            <strong>@selectedCourseTitle</strong> has been received.</p>
        <hr />
        <a href="courses" class="btn btn-outline-success">Browse More Courses</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-6">
            <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                <DataAnnotationsValidator />
                <ValidationSummary class="text-danger mb-3" />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <InputText id="studentName" class="form-control" @bind-Value="model.StudentName" />
                    <ValidationMessage For="() => model.StudentName" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" class="form-control" placeholder="e.g., CS123456" @bind-Value="model.StudentId" />
                    <ValidationMessage For="() => model.StudentId" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <InputSelect id="courseId" class="form-select" @bind-Value="model.CourseId">
                        <option value="0">— Select a course —</option>
                        @if (courses is not null)
                        {
                            @foreach (var course in courses)
                            {
                                <option value="@course.Id">@course.Code — @course.Title</option>
                            }
                        }
                    </InputSelect>
                    <ValidationMessage For="() => model.CourseId" class="text-danger" />
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
            </EditForm>
        </div>

        <div class="col-lg-6 d-none d-lg-block">
            <div class="card bg-light border-0">
                <div class="card-body">
                    <h5>How it works</h5>
                    <ol class="mb-0">
                        <li>Enter your full name and student ID.</li>
                        <li>Select the course you'd like to enroll in.</li>
                        <li>Submit the form — the registrar will review your request.</li>
                    </ol>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private EnrollmentRequest model = new();
    private List<Course>? courses;
    private bool submitted;
    private string selectedCourseTitle = string.Empty;

    protected override async Task OnInitializedAsync()
    {
        courses = await CatalogService.GetCoursesAsync();
        if (CourseId.HasValue)
        {
            model.CourseId = CourseId.Value;
        }
    }

    private async Task HandleSubmit()
    {
        selectedCourseTitle = courses?.FirstOrDefault(c => c.Id == model.CourseId)?.Title ?? "the selected course";
        await CatalogService.SubmitEnrollmentAsync(model);
        submitted = true;
    }
}

